final class WordDictionary {
    private final class Node { var children: [Character: Node] = [:]; var isWord = false }
    private let root = Node()

    func addWord(_ word: String) {
        var node = root
        for c in word { node = node.children[c] ?? { let n = Node(); node.children[c] = n; return n }() }
        node.isWord = true
    }

    func search(_ word: String) -> Bool {
        let chars = Array(word)
        func dfs(_ i: Int, _ node: Node) -> Bool {
            if i == chars.count { return node.isWord }
            if chars[i] == "." { return node.children.values.contains { dfs(i + 1, $0) } }
            guard let next = node.children[chars[i]] else { return false }
            return dfs(i + 1, next)
        }
        return dfs(0, root)
    }
}
